/// <reference types="../types/react-table-config" />

import { useVirtualizer, type VirtualItem } from '@tanstack/react-virtual';
import clsx from 'clsx';
import React, { forwardRef, ReactElement, useRef } from 'react';
import {
  ColumnInstance,
  HeaderGroup,
  TableDispatch,
  TableHeaderProps,
} from 'react-table';
import styled from 'styled-components';

import Elevations from '@dynatrace/strato-design-tokens/elevations';
import { ChevronDownSmallIcon } from '@dynatrace/strato-icons';

import {
  DATA_TABLE_SUB_ROW_TRIGGER_ID,
  DATA_TABLE_EXPANDABLE_ROW_TRIGGER_ID,
  DATA_TABLE_SELECTABLE_ROW_TRIGGER_ID,
} from './constants.js';
import { StyledMenuArrow } from './DataTable.styles.js';
import type { CSSFocusStylesObject } from '../../core/hooks/useFocusRing.js';
import { useFocusRing } from '../../core/hooks/useFocusRing.js';
import { useMergeRefs } from '../../core/hooks/useMergeRefs.js';
import { mergeProps as _mergeProps } from '../../core/utils/merge-props.js';
import { Flex } from '../../layouts-core/flex/Flex.js';
import { DataTableResizer } from '../plugins/use-resize-columns/DataTableResizer.js';
import { SortableArrow } from '../plugins/use-sort-by/SortableArrow.js';
import { separateColumnActions } from '../plugins/use-user-actions/actions.js';
import { ColumnActionsMenu } from '../plugins/use-user-actions/components/ColumnActionsMenu.js';
import type {
  UserActionConfig,
  ColumnActionsProvider,
} from '../plugins/use-user-actions/useUserActions.types.js';
import { getIsPrefixColumn, isActionColumn } from '../utils/column-utils.js';

export type DataTableHeaderProps = {
  lastColumn: boolean;
  secondLastColumn: boolean;
  lastColumnIsActionColumn: boolean;
  isParentGroup: boolean;
  column: HeaderGroup;
  substituteColumn?: HeaderGroup;
  dispatch: TableDispatch;
  columnActions: ColumnActionsProvider | null;
  hasRatioWidth?: boolean;
  tableContainerRef: React.RefObject<HTMLDivElement>;
  /** Measure callback for the virtualizer. */
  columnVirtualizerMeasureElement?: (node: Element | null) => void;
  virtualColumnIndex?: number;
};

export type DataTableHeaderGroupProps = {
  parentHeaderGroup?: HeaderGroup;
  childHeaderGroup: HeaderGroup;
  userActions: UserActionConfig;
  dispatch: TableDispatch;
  columnVisibility: {
    [column: string]: 'hidden' | 'visible';
  };
  hasRatioWidth?: boolean;
  tableContainerRef: React.RefObject<HTMLDivElement>;
  columnVirtualizer: ReturnType<typeof useVirtualizer>;
  columnVirtualization: boolean;
  isGridLayout: boolean;
};

export type DataTableHeaderInternalProps = Omit<
  DataTableHeaderProps,
  | 'lastColumn'
  | 'secondLastColumn'
  | 'lastColumnIsActionColumn'
  | 'dispatch'
  | 'columnActions'
  | 'tableContainerRef'
  | 'gridColumnOffset'
> & {
  hasColumnActions: boolean;
  headerButtonRef: React.RefObject<HTMLButtonElement>;
  onClick?: () => void;
};

/** Returns the correct header props for a column header or column group header. */
function getHeaderProps(
  column: HeaderGroup,
  isPrefixColumn: boolean,
): TableHeaderProps {
  // If the column has sub columns defined, the header should not be sortable
  // because there is no way to determine which column should be sorted.
  const hasSubColumns = column.columns && column.columns.length > 0;
  const sortProps = hasSubColumns ? {} : column.getSortByToggleProps();
  const headerCellProps = { ...column.getHeaderProps(sortProps) };

  if (headerCellProps.style && isPrefixColumn) {
    const { flex, width, minWidth, maxWidth, ...cellStyle } =
      headerCellProps.style;

    headerCellProps.style = cellStyle;
    // measure the prefix cell width, so we can set the px value in the grid template and avoid jumping with column virtualization
    headerCellProps.ref = (element: HTMLElement) => {
      if (element) {
        const elementWidth = element.getBoundingClientRect().width;
        column.width = column.maxWidth = column.minWidth = elementWidth;
      }
    };
  }

  return headerCellProps;
}

/** Returns a column actions menu based on the column actions configuration provider. */
function createColumnActionsMenu(
  column: HeaderGroup,
  substituteColumn: HeaderGroup | undefined,
  isParentGroup: boolean,
  ariaLabel: string | null,
  dispatch: TableDispatch,
  defaultActions: ReactElement[],
  customActions: ReactElement[],
  tableUserActions: React.ReactElement | null,
  actualColumn: ColumnInstance,
  tableContainerRef: React.RefObject<HTMLDivElement>,
  headerButtonRef: React.RefObject<HTMLButtonElement>,
  columnVirtualizerMeasureElement?: (node: Element | null) => void,
  virtualColumnIndex?: number,
) {
  return (
    <ColumnActionsMenu
      column={actualColumn}
      tableUserActions={tableUserActions}
      dispatch={dispatch}
      defaultActions={defaultActions}
      customActions={customActions}
      headerButtonRef={headerButtonRef}
      tableContainerRef={tableContainerRef}
      trigger={
        <DataTableHeaderInternal
          column={column}
          isParentGroup={isParentGroup}
          substituteColumn={substituteColumn}
          hasColumnActions={true}
          aria-label={ariaLabel}
          headerButtonRef={headerButtonRef}
          columnVirtualizerMeasureElement={columnVirtualizerMeasureElement}
          virtualColumnIndex={virtualColumnIndex}
        />
      }
    />
  );
}

export const DataTableHeader = (props: DataTableHeaderProps) => {
  const {
    lastColumn,
    secondLastColumn,
    lastColumnIsActionColumn,
    isParentGroup,
    substituteColumn,
    columnActions,
    dispatch,
    hasRatioWidth,
    tableContainerRef,
    columnVirtualizerMeasureElement,
    virtualColumnIndex,
  } = props;

  // ref for action cell button
  const headerButtonRef = useRef<HTMLButtonElement>(null);

  const column = substituteColumn ?? props.column;
  const { id: columnId, canResize, isResizing, isSorted, canSort } = column;
  const isPrefixColumn = getIsPrefixColumn(columnId);
  const headerCellProps: TableHeaderProps = getHeaderProps(
    column,
    isPrefixColumn,
  );
  const ariaLabel: string | null = column['aria-label'] || null;
  const columnHeaders = column.headers;
  const hasSubHeaders = columnHeaders && columnHeaders.length > 0;
  const headerGroup = hasSubHeaders ? columnHeaders[0].parent : null;
  const actualColumn = column.placeholderOf ?? headerGroup ?? column;
  const isPlaceHolderColHeader = column.placeholderOf && hasSubHeaders;

  const { config, ...tableColumn } = actualColumn;
  const tableUserActions: ReactElement | null =
    columnActions && columnActions(tableColumn);

  const { defaultActions, customActions } = separateColumnActions(
    tableUserActions,
    hasSubHeaders,
  );

  const columnHasActions =
    defaultActions.length > 0 ||
    customActions.length > 0 ||
    column.canSortViaUserAction;

  // Column actions are not rendered for the expandable/selectable columns.
  const columnActionsMenu =
    !isPrefixColumn && columnHasActions
      ? createColumnActionsMenu(
          column,
          substituteColumn,
          isParentGroup,
          ariaLabel,
          dispatch,
          defaultActions,
          customActions,
          tableUserActions,
          actualColumn,
          tableContainerRef,
          headerButtonRef,
          columnVirtualizerMeasureElement,
          virtualColumnIndex,
        )
      : null;

  delete headerCellProps.title;

  const columnIsInteractive = columnHasActions || (!hasSubHeaders && canSort);

  if (isActionColumn(columnId) && headerCellProps.style) {
    delete headerCellProps.style.position;
  }

  if (virtualColumnIndex) {
    headerCellProps.style = {
      ...headerCellProps.style,
      gridColumnStart: virtualColumnIndex + 1,
    };
  }

  return (
    <Flex
      {...headerCellProps}
      className={clsx('strato-table-header-cell', {
        'strato-table-header-has-action': columnIsInteractive,
        'strato-table-header-cell-is-resizing': isResizing,
        'strato-table-header-cell-sorted': isSorted,
        'strato-table-prefix-cell': isPrefixColumn,
        'strato-table-cell-for-actions': isActionColumn(columnId),
        'strato-table-header-merge-column-rows':
          isParentGroup && substituteColumn !== undefined,
      })}
    >
      {columnActionsMenu ?? (
        <DataTableHeaderInternal
          column={column}
          isParentGroup={isParentGroup}
          substituteColumn={substituteColumn}
          hasColumnActions={false}
          aria-label={ariaLabel}
          headerButtonRef={headerButtonRef}
          columnVirtualizerMeasureElement={columnVirtualizerMeasureElement}
          virtualColumnIndex={virtualColumnIndex}
        />
      )}

      {canResize &&
        !lastColumn &&
        !isPrefixColumn &&
        !hasRatioWidth &&
        !isPlaceHolderColHeader &&
        !(secondLastColumn && lastColumnIsActionColumn) && (
          <DataTableResizer
            isResizing={isResizing}
            {...column.getResizerProps()}
          />
        )}
    </Flex>
  );
};

const StyledHeaderButton = styled.button<{
  $focusStyle?: CSSFocusStylesObject;
}>(({ $focusStyle }) => ({
  // for remaining styles see StyledDataTable in DataTable.styles.ts
  // increase specificity to make focusStyles take precedence over the all: 'unset' style
  '&&&': {
    ...$focusStyle,
    zIndex: $focusStyle?.boxShadow ? Elevations.Default : 0,
  },
}));

type TableHeaderCellControlsProps = {
  column: HeaderGroup;
  hasColumnActions: boolean;
};
const TableHeaderCellControls = ({
  column,
  hasColumnActions,
}: TableHeaderCellControlsProps) => {
  const isColumnGroup = !column.headers || column.headers.length === 0;

  if (isColumnGroup && column.canSort) {
    return (
      <SortableArrow
        isSorted={column.isSorted}
        isSortedDesc={column.isSortedDesc}
      />
    );
  }
  if (hasColumnActions) {
    const canSortViaUserAction = isColumnGroup && column.canSortViaUserAction;

    return (
      <>
        {canSortViaUserAction && (
          <SortableArrow
            isSorted={column.isSorted}
            isSortedDesc={column.isSortedDesc}
          />
        )}
        <StyledMenuArrow $canSortViaUserAction={canSortViaUserAction ?? false}>
          <ChevronDownSmallIcon />
        </StyledMenuArrow>
      </>
    );
  }

  return null;
};

/**
 * Column header implementation. Needs to be a `forwardRef` in order to also
 * work in combination with a `<Menu.Trigger>`.
 */
export const DataTableHeaderInternal = /* @__PURE__ */ forwardRef<
  HTMLButtonElement,
  DataTableHeaderInternalProps
>((props, forwardedRef) => {
  const {
    isParentGroup,
    substituteColumn,
    hasColumnActions,
    // Explicitly extracting it here, so that it is not spread onto the dom object
    column: propColumn,
    headerButtonRef,
    virtualColumnIndex,
    columnVirtualizerMeasureElement,
    ...remainingProps
  } = props;

  // only add measure element for column virtualization to child columns, header columns don't need to be measured
  const mergedRefs = useMergeRefs([
    forwardedRef,
    headerButtonRef,
    isParentGroup ? null : columnVirtualizerMeasureElement,
  ]);

  const column = substituteColumn ?? propColumn;
  const { id: columnId, alignment, canSort, canSortViaUserAction } = column;
  const isCellSelectable = columnId.includes(
    DATA_TABLE_SELECTABLE_ROW_TRIGGER_ID,
  );
  const isCellExpandable = columnId.includes(
    DATA_TABLE_EXPANDABLE_ROW_TRIGGER_ID,
  );
  const isRowActionsColumn = isActionColumn(columnId);
  const isCellSubRows = columnId.includes(DATA_TABLE_SUB_ROW_TRIGGER_ID);
  const isCustomHeader = typeof column.Header === 'object';
  const isInteractive = canSort || canSortViaUserAction || hasColumnActions;
  const { focusStyles, focusProps } = useFocusRing({
    variant: 'neutral',
  });

  const cellClassNames = clsx('strato-table-header-cellwrapper', {
    'strato-table-cell-alignment-left': alignment === 'left',
    'strato-table-cell-alignment-center': alignment === 'center',
    'strato-table-cell-alignment-right': alignment === 'right',
    'strato-table-cell-alignment-top-left': alignment === 'top-left',
    'strato-table-cell-alignment-top-center': alignment === 'top-center',
    'strato-table-cell-alignment-top-right': alignment === 'top-right',
    'strato-table-cell-alignment-bottom-left': alignment === 'bottom-left',
    'strato-table-cell-alignment-bottom-center': alignment === 'bottom-center',
    'strato-table-cell-alignment-bottom-right': alignment === 'bottom-right',
    'strato-table-cell-expandable': isCellExpandable,
    'strato-table-cell-selectable': isCellSelectable,
    'strato-table-cell-custom-render': isCustomHeader,
    'strato-table-row-actions-column': isRowActionsColumn,
    'strato-table-cell-sub-rows': isCellSubRows,
  });

  const mergedProps = _mergeProps(focusProps, remainingProps);

  // We should not render a Menu/trigger button around the selectable, expandable and custom rendered header cell.
  if (
    isCellSelectable ||
    isCellExpandable ||
    isCustomHeader ||
    isCellSubRows ||
    isRowActionsColumn
  ) {
    return (
      <div
        className={cellClassNames}
        {...mergedProps}
        {...(!isParentGroup && {
          ref: columnVirtualizerMeasureElement,
          'data-index': virtualColumnIndex,
        })}
      >
        <div>{column.render('Header')}</div>
      </div>
    );
  }

  // Note: it is necessary to deconstruct remainingProps onto the button due to it being used as a <Menu.Trigger>
  return (
    <StyledHeaderButton
      {...mergedProps}
      $focusStyle={focusStyles}
      disabled={!isInteractive}
      ref={mergedRefs}
      data-index={isParentGroup ? undefined : virtualColumnIndex}
    >
      <div className={cellClassNames}>
        <div>{column.render('Header')}</div>
        <TableHeaderCellControls
          column={column}
          hasColumnActions={hasColumnActions}
        />
      </div>
    </StyledHeaderButton>
  );
});

// react-table supports only two nested headers.  Considering that,
// render them right in place with all the ux logic for headers.
export const DataTableHeaderGroup = ({
  parentHeaderGroup,
  childHeaderGroup,
  userActions,
  dispatch,
  hasRatioWidth,
  tableContainerRef,
  columnVirtualizer,
  columnVirtualization,
  isGridLayout,
}: DataTableHeaderGroupProps) => {
  const parentHeaderGroupHeaders = parentHeaderGroup
    ? parentHeaderGroup.headers
    : [];
  const parentHeaderGroupProps = parentHeaderGroup?.getHeaderGroupProps();
  const childHeaderGroupProps = childHeaderGroup.getHeaderGroupProps();

  const virtualColumns = columnVirtualizer.getVirtualItems();

  // for flex layout, we need to translate the row by the offset of the first rendered column
  const translateX =
    !isGridLayout && virtualColumns[0]?.start > 0
      ? `translateX(${virtualColumns[0]?.start}px)`
      : undefined;

  const childHeadersVisible =
    !parentHeaderGroup ||
    childHeaderGroup.headers.some(
      (header) => header.isVisible && header.parent,
    );

  const renderedParentHeaders: HeaderGroup[] = [];
  let firstParentIndex = 0;
  let gridColumnOffset = 0;
  if (
    columnVirtualization &&
    parentHeaderGroup &&
    parentHeaderGroupHeaders.length > 0 &&
    virtualColumns.length > 0
  ) {
    // if there are header groups, we need to construct the parent headers from the child headers that are currently rendered
    virtualColumns.forEach((column, index) => {
      const isFirstVirtualColumn = index === 0;
      const childColumn = childHeaderGroup.headers[column.index];
      const parentId = childColumn.parent?.id;
      const lastParentId =
        renderedParentHeaders[renderedParentHeaders.length - 1]?.originalId;
      const header = parentHeaderGroupHeaders.find((header, headerIndex) => {
        let isRequiredHeader = false;

        if (parentId === undefined) {
          // placeholder header
          isRequiredHeader = header.headers[0].id === childColumn.id;
        } else if (parentId !== lastParentId) {
          // group header if not already added
          isRequiredHeader = header.originalId === parentId;
        }
        if (isRequiredHeader && isFirstVirtualColumn) {
          firstParentIndex = headerIndex;
        }
        return isRequiredHeader;
      });

      header && renderedParentHeaders.push(header);
    });

    // iterate over headers before the first parent header and calcualte the required grid offset for correct placement
    [...parentHeaderGroupHeaders]
      .splice(0, firstParentIndex)
      .forEach((header) => {
        gridColumnOffset += header.headers.filter(
          (header) => header.isVisible,
        ).length;
      });

    // add horizontal translation to the parent header if flex layout is active
    if (
      !isGridLayout &&
      virtualColumns[0].start > 0 &&
      parentHeaderGroupProps
    ) {
      parentHeaderGroupProps.style = {
        ...parentHeaderGroupProps.style,
        transform: `translateX(${virtualColumns[0].start}px)`,
      };
    }
  } else {
    // simply render all parent headers if there is not virtualization
    renderedParentHeaders.push(...parentHeaderGroupHeaders);
  }

  // add horizontal translation to the child header if flex layout is active
  if (columnVirtualization && translateX) {
    childHeaderGroupProps.style = {
      ...childHeaderGroupProps.style,
      transform: translateX,
    };
  }

  return (
    <>
      {parentHeaderGroup && (
        <div
          {...parentHeaderGroupProps}
          className={
            childHeadersVisible
              ? 'strato-table-header-parent'
              : 'strato-table-header'
          }
        >
          {renderedParentHeaders.map((column, index) => {
            // if this is a parent and happens to be a place holder for the child header, then we
            // will render the child header here, so get child header as substitute
            const isPrefixColumn = getIsPrefixColumn(column.id);
            const hasSubHeaders = column.headers && column.headers.length > 0;
            const isPlaceHolderColHeader =
              column.placeholderOf && hasSubHeaders;
            const headerGroupId = hasSubHeaders
              ? column.headers[0].parent?.id
              : null;
            const columnId =
              column.placeholderOf?.id ?? headerGroupId ?? column.id;
            const columnActions =
              userActions.columnActionProviders[columnId] ??
              userActions.defaultColumnActionProvider;

            // if there are header groups before the current header, we need save the offset for the placement in the grid
            const prevColumnIndex = index - 1;
            if (prevColumnIndex >= 0) {
              gridColumnOffset +=
                renderedParentHeaders[prevColumnIndex].headers.filter(
                  (header) => header.isVisible,
                ).length - 1;
            }

            const isLastColumn = index === renderedParentHeaders.length - 1;
            const lastColumnId =
              renderedParentHeaders[renderedParentHeaders.length - 1].id;
            const lastColumnIsActionColumn = isActionColumn(lastColumnId);
            const isSecondLastColumn =
              renderedParentHeaders.length > 2 &&
              index === renderedParentHeaders.length - 2;

            return (
              <DataTableHeader
                key={`strato-table-parent-header-${index}`}
                column={column}
                lastColumn={isLastColumn}
                secondLastColumn={isSecondLastColumn}
                lastColumnIsActionColumn={lastColumnIsActionColumn}
                isParentGroup={childHeadersVisible}
                substituteColumn={
                  !isPrefixColumn && isPlaceHolderColHeader
                    ? column.headers[0]
                    : undefined
                }
                dispatch={dispatch}
                columnActions={columnActions}
                hasRatioWidth={hasRatioWidth}
                tableContainerRef={tableContainerRef}
                columnVirtualizerMeasureElement={
                  columnVirtualizer.measureElement
                }
                virtualColumnIndex={index + gridColumnOffset}
              />
            );
          })}
        </div>
      )}
      {childHeadersVisible && (
        <div {...childHeaderGroupProps} className={'strato-table-header'}>
          {(columnVirtualization
            ? virtualColumns
            : childHeaderGroup.headers
          ).map((columnItem: VirtualItem | HeaderGroup, index: number) => {
            let column: HeaderGroup = columnItem as HeaderGroup;
            let key: string | number = `strato-table-header-${index}`;
            let columnIndex = index;
            if ('start' in columnItem) {
              column = childHeaderGroup.headers[columnItem.index];
              key = columnItem.key;
              columnIndex = columnItem.index;
            }
            // only if not a child header
            // if this happens to have a place holder in the parent header get
            // that header so we can render this child header column with that
            // as we already replaced parent with the this one.
            const substituteColumn = column.parent
              ? undefined
              : parentHeaderGroupHeaders.find(
                  (parentColumn) =>
                    parentColumn.placeholderOf &&
                    parentColumn.headers &&
                    parentColumn.headers.length > 0 &&
                    parentColumn.headers[0].id === column.id &&
                    !getIsPrefixColumn(column.id),
                );
            // If the substituted column has a placeholderOf member, this means
            // that this transposed cell will be a placeholder column. The actions
            // will move to the other one.
            const columnActions = substituteColumn?.placeholderOf
              ? null
              : userActions.columnActionProviders[column.id] ??
                userActions.defaultColumnActionProvider;

            return (
              <DataTableHeader
                key={key}
                column={column}
                lastColumn={columnIndex === childHeaderGroup.headers.length - 1}
                secondLastColumn={false}
                lastColumnIsActionColumn={false}
                isParentGroup={false}
                substituteColumn={substituteColumn}
                dispatch={dispatch}
                columnActions={columnActions}
                tableContainerRef={tableContainerRef}
                {...(columnVirtualization && {
                  columnVirtualizerMeasureElement:
                    columnVirtualizer.measureElement,
                  virtualColumnIndex: columnIndex,
                })}
              />
            );
          })}
        </div>
      )}
    </>
  );
};
